<h1>Seller Reviews</h1>
<section class="stats-row"><div class="card"><strong><?=$d['review_count']?H::e(number_format((float)$d['average_rating'],1)).' ★':'No reviews yet'?></strong><span><?=$d['review_count']?(int)$d['review_count'].' reviews':''?></span></div><?php for($n=5;$n>=1;$n--):?><div class="card"><strong><?=(int)$d['rating_'.$n.'_count']?></strong><span><?=$n?> star</span></div><?php endfor;?></section>
<?php if(!(int)$d['review_count']):?><div class="card empty-state"><h2>No reviews yet</h2><p>Verified buyer reviews will appear after a successfully downloaded purchase is reviewed.</p></div><?php endif;?>
<form method="get" class="card"><label>Filter <select name="filter"><?php foreach(['all'=>'All','5'=>'5 Stars','4'=>'4 Stars','3'=>'3 Stars','2'=>'2 Stars','1'=>'1 Star','replied'=>'Replied','needs_reply'=>'Needs Reply'] as $v=>$label):?><option value="<?=$v?>" <?=$filter===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>Sort <select name="sort"><?php foreach(['newest'=>'Newest','oldest'=>'Oldest','highest'=>'Highest Rating','lowest'=>'Lowest Rating'] as $v=>$label):?><option value="<?=$v?>" <?=$sort===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button>Apply</button></form>
<?php foreach($reviews as $r):?><article class="card" id="review-<?=(int)$r['id']?>"><h2><?=H::e($r['product_title_snapshot'])?></h2><p><?=str_repeat('★',(int)$r['rating'])?> · <?=H::e($r['buyer_name_snapshot'])?> · <?=H::e($r['reviewed_at'])?></p><?php if($r['review_text']):?><p><?=nl2br(H::e($r['review_text']))?></p><?php endif;?>
<?php if($r['reply_text']):?><p><strong>Seller Response<?=$r['reply_moderation_status']==='removed'?' — Removed by Admin':''?></strong></p><p><?=nl2br(H::e($r['reply_text']))?></p><small><?=H::e($r['reply_created_at'])?><?php if(strtotime($r['reply_updated_at'])>strtotime($r['reply_created_at'])):?> · Edited<?php endif;?></small><?php endif;?>
<?php if($r['reply_moderation_status']!=='removed'):?><form method="post" action="/seller/reviews/<?=(int)$r['id']?>/reply"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><label>Public response<textarea name="reply_text" maxlength="2000" required><?=H::e($r['reply_text']??'')?></textarea></label><button>Save Response</button></form><?php endif;?>
<?php if(!$r['reported']):?><details><summary>Report review</summary><form method="post" action="/seller/reviews/<?=(int)$r['id']?>/report"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><select name="reason" required><option value="spam">Spam</option><option value="harassment">Harassment</option><option value="personal_information">Personal information</option><option value="hate_threatening">Hate/threatening content</option><option value="unrelated">Review unrelated to transaction</option><option value="other">Other</option></select><textarea name="details" maxlength="2000" aria-label="Report details"></textarea><button>Submit Report</button></form></details><?php else:?><p><small>Reported to Admin; review visibility is unchanged.</small></p><?php endif;?></article><?php endforeach;?>
